#!/usr/bin/env bats
# test_scripts.bats - BATS test suite for defensive shell scripts
# Tests safe_backup.sh and common_utils.sh

# Setup and teardown
setup() {
    # Create temporary test directories
    export TEST_DIR="$(mktemp -d)"
    export SOURCE_DIR="${TEST_DIR}/source"
    export BACKUP_DIR="${TEST_DIR}/backups"

    mkdir -p "${SOURCE_DIR}" "${BACKUP_DIR}"

    # Create test files
    echo "test content" > "${SOURCE_DIR}/file1.txt"
    echo "more content" > "${SOURCE_DIR}/file2.txt"
    mkdir -p "${SOURCE_DIR}/subdir"
    echo "nested file" > "${SOURCE_DIR}/subdir/file3.txt"
}

teardown() {
    # Clean up test directories
    if [[ -n "${TEST_DIR}" && -d "${TEST_DIR}" ]]; then
        rm -rf "${TEST_DIR}"
    fi
}

# Test common_utils.sh
@test "common_utils.sh: script sources without errors" {
    source test/common_utils.sh
}

@test "common_utils.sh: command_exists detects existing command" {
    source test/common_utils.sh
    run command_exists bash
    [ "$status" -eq 0 ]
}

@test "common_utils.sh: command_exists fails for non-existent command" {
    source test/common_utils.sh
    run command_exists nonexistent_command_xyz
    [ "$status" -ne 0 ]
}

@test "common_utils.sh: validate_directory succeeds for valid directory" {
    source test/common_utils.sh
    run validate_directory "${TEST_DIR}"
    [ "$status" -eq 0 ]
}

@test "common_utils.sh: validate_directory fails for non-existent directory" {
    source test/common_utils.sh
    run validate_directory "/nonexistent/path"
    [ "$status" -ne 0 ]
}

@test "common_utils.sh: create_directory creates new directory" {
    source test/common_utils.sh
    local new_dir="${TEST_DIR}/new_directory"
    run create_directory "${new_dir}"
    [ "$status" -eq 0 ]
    [ -d "${new_dir}" ]
}

@test "common_utils.sh: get_absolute_path returns absolute path" {
    source test/common_utils.sh
    run get_absolute_path "${SOURCE_DIR}"
    [ "$status" -eq 0 ]
    [[ "${output}" == /* ]]
}

# Test safe_backup.sh
@test "safe_backup.sh: shows help with -h flag" {
    run test/safe_backup.sh -h
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "Usage:" ]]
}

@test "safe_backup.sh: shows version with -v flag" {
    run test/safe_backup.sh -v
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "version" ]]
}

@test "safe_backup.sh: fails with no arguments" {
    run test/safe_backup.sh
    [ "$status" -eq 1 ]
}

@test "safe_backup.sh: fails with only source argument" {
    run test/safe_backup.sh "${SOURCE_DIR}"
    [ "$status" -eq 1 ]
}

@test "safe_backup.sh: fails with non-existent source directory" {
    run test/safe_backup.sh /nonexistent/source "${BACKUP_DIR}"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh: creates backup successfully" {
    run test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Check that backup file was created
    local backup_count
    backup_count=$(find "${BACKUP_DIR}" -name "*.tar.gz" | wc -l)
    [ "${backup_count}" -eq 1 ]
}

@test "safe_backup.sh: backup file is valid tar.gz" {
    run test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Find the created backup
    local backup_file
    backup_file=$(find "${BACKUP_DIR}" -name "*.tar.gz" | head -n 1)

    # Verify it's a valid gzip file
    run file "${backup_file}"
    [[ "${output}" =~ "gzip compressed data" ]]
}

@test "safe_backup.sh: backup contains original files" {
    run test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Find the created backup
    local backup_file
    backup_file=$(find "${BACKUP_DIR}" -name "*.tar.gz" | head -n 1)

    # List contents
    run tar -tzf "${backup_file}"
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "file1.txt" ]]
    [[ "${output}" =~ "file2.txt" ]]
}

@test "safe_backup.sh: custom backup name works" {
    run test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}" "custom_name"
    [ "$status" -eq 0 ]

    # Check that backup with custom name was created
    local backup_count
    backup_count=$(find "${BACKUP_DIR}" -name "custom_name.backup-*.tar.gz" | wc -l)
    [ "${backup_count}" -eq 1 ]
}

@test "safe_backup.sh: creates destination directory if missing" {
    local new_backup_dir="${TEST_DIR}/new_backups"
    run test/safe_backup.sh "${SOURCE_DIR}" "${new_backup_dir}"
    [ "$status" -eq 0 ]
    [ -d "${new_backup_dir}" ]
}

# ShellCheck validation tests
@test "common_utils.sh passes shellcheck" {
    command -v shellcheck >/dev/null 2>&1 || skip "shellcheck not installed"
    run shellcheck --severity=warning test/common_utils.sh
    [ "$status" -eq 0 ]
}

@test "safe_backup.sh passes shellcheck" {
    command -v shellcheck >/dev/null 2>&1 || skip "shellcheck not installed"
    run shellcheck --severity=warning test/safe_backup.sh
    [ "$status" -eq 0 ]
}

